const files=JSON.parse(gunzipSync(Buffer.from(payload.replace(/\s/g,''),'base64')));
const target=resolve(process.argv[2] || 'mobile');
if(existsSync(target) && readdirSync(target).length) throw Error('Target directory must be empty; existing work will not be overwritten.');
for(const item of files){
 const output=resolve(target,item.path);
 if(!output.startsWith(target+sep)) throw Error('Invalid source path');
 const data=Buffer.from(item.data,'base64');
 if(createHash('sha256').update(data).digest('hex')!==item.sha256) throw Error('Source checksum mismatch');
}
mkdirSync(target,{recursive:true});
for(const item of files){const output=resolve(target,item.path);mkdirSync(dirname(output),{recursive:true});writeFileSync(output,Buffer.from(item.data,'base64'),{flag:'wx'});}
console.log('LimonUp native source extracted: '+files.length+' files in '+target+'. Read README.md for build and test instructions.');
